def main(out_path):
    seq = 0
    pages = []
    for folio, desc, cands, conf, la, it, de in P:
        if folio.startswith("cover"):
            page = None
        else:
            seq += 1
            page = str(seq)
        crib = []
        for word in la + it + de:
            if word not in crib:
                crib.append(word)
        pages.append({
            "page": page,
            "folio": folio,
            "description": desc,
            "candidates_en": cands,
            "confidence": conf,
            "crib": crib,
            "crib_by_language": {"la": la, "it": it, "de": de},
        })
    folios = [p["folio"] for p in pages]
    assert len(folios) == len(set(folios)) == 71, len(folios)
    doc = {
        "source": "Yale Beinecke MS 408 (Cipher manuscript) page scans, image IDs 1006074-1006144, supplied as two PDFs by the user",
        "method": "Visual identification from the scans only; no external Voynich identification literature consulted in this session. AI-generated, exploratory.",
        "page_numbering": "'page' counts scanned folio sides from 1r = 1 (so 2v = 4); covers have page null. 'folio' is the foliation on the scan. Folio 12 is absent from the scans.",
        "crib_languages": {"la": "medieval Latin herbal/apothecary names", "it": "Italian vernacular (Tuscan/northern forms)", "de": "Middle/Early New High German"},
        "pages": pages,
    }
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(doc, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1])
